/* Simulations: save is allowed; PDF is locked until a paid order exists. */
const rc12BaseEnhanceCalculator=rc11EnhanceCalculator;
rc11EnhanceCalculator=function(){
 if(currentView!=='calculator'||!currentClient())return;
 const host=$('content');if(host&&!host.querySelector('.rc11-calculator-lock'))host.insertAdjacentHTML('afterbegin',`<div class="rc11-calculator-lock"><b>Simulation workflow</b>Save your calculation for ${rc12Settings().simulationRetentionDays} days. PDF export is unlocked from the paid order/invoice workflow only.</div>`);
 document.querySelectorAll('#content .toolbar button').forEach(b=>{const txt=b.textContent.trim().toLowerCase();if(txt.includes('pdf'))b.remove()});
 document.querySelectorAll('#systemInput option').forEach(o=>{const s=SYSTEMS.find(x=>x.id===o.value);if(s?.rc11Archived)o.disabled=true});
};
const rc12BaseBindCalculator=bindCalculator;
bindCalculator=function(){
 rc12BaseBindCalculator();const save=$('saveSimulation');if(save)save.onclick=()=>{if(!result)return toast('Run the calculation first.');const copy=JSON.parse(JSON.stringify(result));copy.createdAt=new Date().toISOString();copy.expiresAt=new Date(Date.now()+rc12Settings().simulationRetentionDays*86400000).toISOString();tenantData().simulations.unshift(copy);saveStore();toast(`Simulation saved for ${rc12Settings().simulationRetentionDays} days.`)};
};
