/* ================= RENOVO CRETE V13 — governance, dossiers, territory drill-down, pricing & 2-page documents ================ */
const RC13_VERSION='V13 GOVERNANCE & DOCUMENTS';
const RC13_CURRENT_YEAR=new Date().getFullYear();
const RC13_CLIENT_TYPES=['Subcontractor','Applicator','Subcontractor / Applicator','Architect','Specifier','General contractor','Project manager','Designer','Distributor','Employee','Professional client','Other'];

function rc13Settings(){
 const s=rc12Settings();
 s.globalEcsCatalogPrices=s.globalEcsCatalogPrices||{};
 s.scopeResalePrices=s.scopeResalePrices||{};
 s.scopeExchangeRates=s.scopeExchangeRates||{};
 s.pricingTarget=s.pricingTarget||'REGION:CARIBBEAN';
 s.operationalYear=Math.min(RC13_CURRENT_YEAR,Math.max(2026,Number(s.operationalYear||2026)));
 s.caribbeanGlobalReadOnly=s.caribbeanGlobalReadOnly!==false;
 s.allowCaribbeanProfessionalSelfRegistration=!!s.allowCaribbeanProfessionalSelfRegistration;
 s.registrationReservations=s.registrationReservations||{};
 s.hubspot=s.hubspot||{enabled:false,proxyUrl:'',portalId:''};
 s.selectedTerritoryId=s.selectedTerritoryId||'';
 s.territoryTab=s.territoryTab||'overview';
 s.adminCalculatorClientId=s.adminCalculatorClientId||'';
 s.adminSimulations=Array.isArray(s.adminSimulations)?s.adminSimulations:[];
 return s;
}
function rc13IsCaribbeanGlobalView(p=rc11AdminProfile()){return rc12IsCaribbeanHq(p)&&rc13Settings().caribbeanGlobalReadOnly}
function rc13IsHq(p=rc11AdminProfile()){return rc12IsWorldHq(p)||rc12IsCaribbeanHq(p)}
function rc13Safe(v){return esc(String(v??''))}
function rc13CurrentYearOptions(){return Array.from({length:Math.max(1,RC13_CURRENT_YEAR-2026+1)},(_,i)=>2026+i)}
function rc13ClientTypeOptions(selected=''){return RC13_CLIENT_TYPES.map(x=>`<option value="${rc13Safe(x)}" ${selected===x?'selected':''}>${rc13Safe(x)}</option>`).join('')}
function rc13DeptName(id){return rc13Settings().departments.find(d=>d.id===id)?.name||'Not assigned'}
function rc13TerritoryClaimed(id,exceptAdminId=''){
 if(id==='usa-indiana-hq')return true;
 if(rc11Territory(id)?.regionId==='CARIBBEAN')return true;
 return (store.adminProfiles||[]).some(a=>a.id!==exceptAdminId&&a.territoryId===id&&a.level==='regional_admin'&&a.active!==false)||!!rc13Settings().registrationReservations[id];
}
function rc13RegistrationTerritories(){return rc11Territories().filter(t=>t.regionId!=='CARIBBEAN'&&t.id!=='usa-indiana-hq'&&!rc13TerritoryClaimed(t.id))}

/* Caribbean HQ may inspect worldwide data read-only, while management stays Caribbean-only. */
rc12AllowedRegions=function(p=rc11AdminProfile()){
 if(!p)return[];
 if(rc12IsWorldHq(p)||rc13IsCaribbeanGlobalView(p))return RC11_REGION_SEED.map(r=>r.id);
 if(rc12IsCaribbeanHq(p))return['CARIBBEAN'];
 return [...new Set([p.regionId,...(p.extraRegionIds||[])].filter(Boolean))];
};
rc12AllowedTerritories=function(p=rc11AdminProfile(),regionId=''){
 if(!p)return[];
 if(rc12IsWorldHq(p)||rc13IsCaribbeanGlobalView(p))return rc11Territories(regionId).map(t=>t.id);
 if(rc12IsCaribbeanHq(p))return regionId&&regionId!=='CARIBBEAN'?[]:rc11Territories('CARIBBEAN').map(t=>t.id);
 if(regionId&&(p.extraRegionIds||[]).includes(regionId))return rc11Territories(regionId).filter(t=>t.id!=='car-saint-martin').map(t=>t.id);
 return [...new Set([p.territoryId,...(p.extraTerritoryIds||[])].filter(Boolean))].filter(id=>(!regionId||rc11Territory(id)?.regionId===regionId)&&id!=='car-saint-martin');
};
rc11CanSeeClient=function(c,p=rc11AdminProfile()){
 if(!p||!c)return false;
 if(c.territoryId==='car-saint-martin')return rc12IsWorldHq(p)||rc12IsCaribbeanHq(p);
 if(rc12IsWorldHq(p)||rc13IsCaribbeanGlobalView(p))return true;
 if(rc12IsCaribbeanHq(p))return c.regionId==='CARIBBEAN';
 return rc12AllowedTerritories(p,c.regionId).includes(c.territoryId)||(p.extraRegionIds||[]).includes(c.regionId);
};
rc11CanManageClient=function(c,p=rc11AdminProfile()){
 if(!p||!c||!rc12AdminPerms(p).manageProfessionals)return false;
 if(rc12IsWorldHq(p))return true;
 if(rc12IsCaribbeanHq(p))return c.regionId==='CARIBBEAN';
 if(c.territoryId==='car-saint-martin')return false;
 return rc12AllowedTerritories(p,c.regionId).includes(c.territoryId)||(p.extraRegionIds||[]).includes(c.regionId);
};
rc11CanSeeAdmin=function(a,p=rc11AdminProfile()){
 if(!p||!a)return false;
 if(a.territoryId==='car-saint-martin')return rc12IsWorldHq(p)||rc12IsCaribbeanHq(p);
 if(rc12IsWorldHq(p)||rc13IsCaribbeanGlobalView(p))return true;
 if(rc12IsCaribbeanHq(p))return a.regionId==='CARIBBEAN';
 return rc12AllowedTerritories(p,a.regionId).includes(a.territoryId)||(p.extraRegionIds||[]).includes(a.regionId);
};
rc11CanManageAdmin=function(a,p=rc11AdminProfile()){
 if(!p||!a||!rc12AdminPerms(p).manageAdmins)return false;
 if(a.id===p.id)return true;
 if(a.protected||['global_hq','caribbean_hq'].includes(a.level))return false;
 if(rc12IsWorldHq(p))return true;
 if(rc12IsCaribbeanHq(p))return a.regionId==='CARIBBEAN';
 return a.territoryId===p.territoryId&&!a.protected;
};
rc12CanCreateAdminIn=function(regionId,territoryId,p=rc11AdminProfile()){
 if(!p||!rc12AdminPerms(p).manageAdmins||territoryId==='car-saint-martin')return false;
 if(rc12IsWorldHq(p))return true;
 if(rc12IsCaribbeanHq(p))return regionId==='CARIBBEAN';
 return territoryId===p.territoryId;
};

