renderRegionsV11=function(){const p=rc11AdminProfile(),regions=rc12AllowedRegionObjects(p),clients=(store.accounts||[]).filter(c=>c.role==='client'&&rc11CanSeeClient(c,p)),orders=rc11OrdersFor(clients);return rc11Hero('Regions & territories','Each region can be collapsed. Open a territory for its complete administrator, professional, order, invoice and export workspace.','ACCESS GOVERNANCE',rc12CanManageTerritories(p)?'<button class="btn primary" id="rc11AddTerritory">Add territory</button>':'',[`${regions.length} visible regions`])+rc11AccessNote()+`<section class="rc11-panel"><div class="rc13-region-grid">${regions.map((r,ri)=>{const ts=rc11Territories(r.id).filter(t=>rc12AllowedTerritories(p,r.id).includes(t.id)),cs=clients.filter(c=>c.regionId===r.id),os=orders.filter(o=>o.client.regionId===r.id),col=os.reduce((n,x)=>n+rcOrderPaid(x.order),0);return`<details class="rc13-region-card" data-rc13-region-details ${ri===0?'open':''}><summary><span><b>${r.flag} ${rc13Safe(rc11RegionName(r.id))}</b><small>${ts.length} territories · ${cs.length} professionals</small></span><span class="rc13-chevron">⌄</span></summary><div class="rc13-region-body"><div class="rc11-region-stats"><div><small>Collected</small><b>${rc11Money(col)}</b></div><div><small>Orders</small><b>${os.length}</b></div><div><small>Professionals</small><b>${cs.length}</b></div></div><div class="rc13-territory-list">${ts.map(t=>{const d=rc13TerritoryDataset(t);return`<button class="rc13-territory-row" data-rc13-territory-open="${rc13Safe(t.id)}"><span><b>${rc13Safe(t.name)}</b><small>${rc13Safe(t.city||'')}</small></span><span>${d.clients.length} pros · ${d.admins.length} admins</span><b>Open →</b></button>`}).join('')||'<div class="rc12-empty">No authorized territory.</div>'}</div></div></details>`}).join('')}</div></section>`}
