async function rc13ImportTerritoryFile(file){if(!file)return;const t=rc11Territory(rc13Settings().selectedTerritoryId);if(!t)return;if(file.name.toLowerCase().endsWith('.csv')){const text=await file.text(),lines=text.split(/\r?\n/).filter(Boolean),headers=lines.shift().split(/[;,]/).map(x=>x.replace(/^"|"$/g,'').trim().toLowerCase()),created=[];for(const line of lines){const vals=line.split(/[;,]/).map(x=>x.replace(/^"|"$/g,'').trim()),o=Object.fromEntries(headers.map((h,i)=>[h,vals[i]||'']));if(!o.email&&!o.company)continue;const id=rc11SafeId('client-import'),first=o.firstname||o['first name']||'',last=o.lastname||o['last name']||'';store.accounts.push({id,role:'client',company:o.company||`${first} ${last}`.trim()||'Imported professional',legalName:o.legalname||o.company||'',firstName:first,lastName:last,contact:`${first} ${last}`.trim(),email:(o.email||'').toLowerCase(),phone:o.phone||'',clientType:o.type||o.clienttype||'Professional client',registrationNumber:o.siret||o.registration||'',siret:o.siret||o.registration||'',address1:o.address||'',postalCode:o.postal||o.zip||'',city:o.city||t.city||'',country:t.name,regionId:t.regionId,territoryId:t.id,active:false,status:'pending',priceTier:'recommended',catalogAccess:false,createdAt:new Date().toISOString()});store.tenants[id]={cart:[],simulations:[],orders:[],documents:[],productChoices:{},packChoices:{},lineOverrides:{},customLines:{},visualSelection:null,messages:[],notifications:[]};created.push(id)}saveStore();renderShell();toast(`${created.length} pending professional record(s) imported from CSV.`)}else{const meta={id:rc11SafeId('import'),name:file.name,type:file.type,size:file.size,territoryId:t.id,createdAt:new Date().toISOString()};rc13Settings().pendingImportFiles=rc13Settings().pendingImportFiles||[];rc13Settings().pendingImportFiles.unshift(meta);saveStore();toast('Excel/PDF document registered for assisted import. Server-side parsing will be used in production to preserve field accuracy.')}}
