function renderAdminSavedSimulationsV13(){const rows=rc13Settings().adminSimulations;return rc11Hero('Administrator saved simulations','Permanent admin comparison workspace. Unlike professional temporary simulations, these records are retained until an administrator deletes them.','ADMIN SIMULATIONS','',[`${rows.length} saved`])+`<div class="rc13-smart-filter"><div class="field"><label>Search</label><input id="rc13AdminSimSearch" placeholder="Client, territory, system"></div><div class="field"><label>Year</label><select id="rc13AdminSimYear"><option value="">All</option>${rc13CurrentYearOptions().map(y=>`<option>${y}</option>`).join('')}</select></div></div><div class="rc11-entity-list" id="rc13AdminSimList" data-view-mode="medium">${rows.map((s,i)=>`<article class="rc11-entity-card rc13-admin-sim" data-search="${rc13Safe([s.clientCompany,s.system?.name,rc11Territory(s.territoryId)?.name,s.project].join(' ').toLowerCase())}" data-year="${new Date(s.createdAt).getFullYear()}"><span class="rc11-number">${String(i+1).padStart(3,'0')}</span><div class="rc11-card-body"><h3>${rc13Safe(s.system?.name||'Simulation')}</h3><p>${rc13Safe(s.clientCompany||'')} · ${rc13Safe(rc11Territory(s.territoryId)?.name||'')}</p><div class="meta"><span>${rc13Safe(rc11Date(s.createdAt,true))}</span><span>${num.format(s.areaM2||0)} m² / ${num.format(s.areaSqft||0)} sqft</span><span>${rc11Money(s.summary?.totalEUR||0)}</span></div><div class="toolbar"><button class="btn primary small" data-rc13-admin-sim-pdf="${i}">PDF — 2 pages</button><button class="btn secondary small" data-rc13-admin-sim-xls="${i}">Excel</button><button class="btn danger small" data-rc13-admin-sim-delete="${i}">Delete</button></div></div></article>`).join('')||'<div class="rc12-empty">No administrator simulation saved.</div>'}</div>`}
