function rc13TechnicalChecklist(comment=''){const q=String(comment||'').toLowerCase(),extra=[];if(/crack|fissur/.test(q))extra.push('Cracks/fissures reported: inspect, open/repair as prescribed and verify movement before coating.');if(/hole|trou|spall|nid/.test(q))extra.push('Holes/spalls reported: plan approved repair mortar/patching before the flooring system.');if(/moist|humid|water|eau/.test(q))extra.push('Moisture/water concern reported: perform the required substrate moisture testing and select the approved primer/vapor-control strategy.');return [...extra,'Verify substrate condition, cleanliness, profile, cracks, joints, moisture and drainage before application.','Prepare PPE: gloves, eye protection, suitable respiratory protection where required, protective clothing and safety footwear.','Prepare clean mixing pails, calibrated mixer/paddle, measuring tools, rollers/squeegees/trowels appropriate to the selected system, masking and cleaning materials.','Use isopropyl alcohol or any cleaning solvent only where the selected Elite Crete Systems procedure explicitly permits it.','Final product selection, coverage rate and application sequence must be validated against the current technical data / submittal package before installation.']}
function rc13SimulationDoc(sim,title='TECHNICAL SIMULATION'){const rows=rc13SimulationRows(sim),check=rc13TechnicalChecklist(sim.comment),sys=sim.system||SYSTEMS.find(s=>s.id===sim.systemId)||{},layers=(sim.lines||[]).map((l,i)=>`<li><b>${i+1}. ${rc13Safe(l.layer?.name||'Layer')}</b> — ${rc13Safe(l.productName||'Product')} · need ${num.format(l.need||0)} ${rc13Safe(unitLabel(l.unit,true))} · rate ${l.rate?num.format(l.rate)+' '+rc13Safe(l.layer?.rateUnit||''):'to validate'}</li>`).join('');return`<section class="page"><div class="head"><div><h1>RENOVO CRETE</h1><b>${rc13Safe(title)}</b></div><div>${rc13Safe(sim.id||'')}<br>${rc13Safe(rc11Date(sim.createdAt,true))}</div></div><div class="grid"><div class="box"><b>Client / context</b><br>${rc13Safe(sim.clientCompany||sim.client||'')}<br>${rc13Safe(rc11Territory(sim.territoryId)?.name||'')}</div><div class="box"><b>Project</b><br>${rc13Safe(sim.project||'—')}<br>${num.format(sim.areaM2||0)} m² / ${num.format(sim.areaSqft||0)} sqft</div><div class="box"><b>System</b><br>${rc13Safe(sys.name||'')}</div><div class="box"><b>Total products</b><br>${rc11Money(sim.summary?.totalEUR||0)}<br>${sim.summary?.totalUSD?rc11Money(sim.summary.totalUSD,'USD'):''}</div></div><h2>Products, packs & coverage</h2><table><thead><tr><th>Layer</th><th>Product</th><th>Pack</th><th>Qty</th><th>Unit price</th><th>Total</th><th>Need / coverage basis</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.layer}. ${rc13Safe(r.layerName)}</td><td>${rc13Safe(r.product)}</td><td>${rc13Safe(r.pack)}</td><td>${num.format(r.qty||0)}</td><td>${rc11Money(r.unit||0)}</td><td>${rc11Money(r.total||0)}</td><td>${num.format(r.need||0)} · ${r.rate?num.format(r.rate)+' '+rc13Safe(r.rateUnit):'validate rate'}</td></tr>`).join('')}</tbody></table><div class="box"><b>Project comment</b><br>${rc13Safe(sim.comment||'No project comment.')}</div></section><section class="page"><div class="head"><div><h1>System build-up & preparation</h1><b>${rc13Safe(sys.name||'')}</b></div><div class="badge">Educational summary</div></div><div class="grid"><div class="box">${rc13SystemVisual(sys.id,sys.name)}</div><div class="box"><h3>Layer sequence</h3><ol>${layers}</ol></div></div><h2>Pre-job checklist / points to plan</h2><ul>${check.map(x=>`<li>${rc13Safe(x)}</li>`).join('')}</ul><div class="box"><b>Technical notice</b><br>This document is a calculation and planning aid. It does not replace substrate testing, current Elite Crete Systems technical data, SDS, project specifications or installer training.</div></section>`}
