function rc13ExportAdminSimXLS(i){const s=rc13Settings().adminSimulations[i];if(!s)return;const rows=rc13SimulationRows(s).map(r=>[r.layer,r.layerName,r.product,r.pack,r.qty,r.unit,r.total,r.need,r.rate,r.rateUnit,r.purchased,r.remainder]);rc13Download(`${s.id||'simulation'}.xls`,rc13XlsTable(`${s.system?.name||'Simulation'} — ${s.clientCompany||''}`,['Layer','Layer name','Product','Pack','Qty','Unit price EUR','Total EUR','Need','Rate','Rate unit','Purchased','Remainder'],rows),'application/vnd.ms-excel;charset=utf-8')}

