rc11OpenInvoice=function(number){const x=rc11FindInvoice(number);if(!x)return toast('No permission.');const v=x.invoice,found=rc13FindOrderForInvoice(v),o=found?.order||{},c=found?.client||x.client,systemId=o.systemId||(o.items||[]).find(i=>i.systemId)?.systemId||'',systemName=v.systemName||o.systemName||rcSystemKey(o),areaM2=Number(o.areaM2||(o.items||[]).find(i=>i.systemAreaM2)?.systemAreaM2||0),areaSqft=areaM2*SQFT_PER_M2,items=v.items||[],check=rc13TechnicalChecklist(o.comment||o.siteNotes||v.notes||''),layers=(SYSTEMS.find(s=>s.id===systemId)?.layers||[]).map((l,i)=>`<li><b>${i+1}. ${rc13Safe(l.name)}</b>${l.rate?` — ${num.format(l.rate)} ${rc13Safe(l.rateUnit||'')}`:''}</li>`).join('');showModal(`<article class="rc11-invoice-sheet rc13-invoice-two-page"><section class="rc13-invoice-page"><header><div><small>INVOICE / MATERIAL SUPPLY</small><h2>${rc13Safe(v.number)}</h2><p>${rc13Safe(rc11Date(v.issuedAt))}</p></div><div class="invoice-brand"><b>RENOVO CRETE</b><span>${rc13Safe(rc11RegionName(v.regionId))} · ${rc13Safe(rc11TerritoryLabel(v.territoryId))}</span><br><small>Territory-specific numbered invoice</small></div></header><div class="rc11-invoice-parties"><section><small>Bill to</small><h3>${rc13Safe(v.company)}</h3><p>${rc13Safe(v.clientName)}<br>${rc13Safe(c?.address1||v.address||'')}<br>${rc13Safe([c?.postalCode,c?.city].filter(Boolean).join(' '))}<br>${rc13Safe(v.email||'')}<br>${rc13Safe(c?.registrationNumber||c?.siret||'')}</p></section><section><small>Project / order</small><h3>${rc13Safe(v.orderNumber)}</h3><p>${rc13Safe(v.project||'')}<br>${rc13Safe(systemName)}<br>${areaM2?`${num.format(areaM2)} m² / ${num.format(areaSqft)} sqft`:''}</p></section></div><div class="table-wrap"><table class="rc11-table"><thead><tr><th>Product</th><th>Pack</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody>${items.map(i=>`<tr><td>${rc13Safe(i.product||i.systemName||systemName)}</td><td>${rc13Safe(i.pack||'—')}</td><td>${num.format(Number(i.quantity||0))}</td><td>${rc11Money(i.unitPriceEUR||0)}</td><td><b>${rc11Money(i.totalEUR||0)}</b></td></tr>`).join('')}</tbody></table></div><div class="rc11-invoice-total"><div><span>Total EUR</span><b>${rc11Money(v.totalEUR)}</b></div>${v.totalUSD?`<div><span>Total USD</span><b>${rc11Money(v.totalUSD,'USD')}</b></div>`:''}<div class="grand"><span>Paid / confirmed</span><b>${rc11Money(v.totalEUR)}</b></div></div><div class="rc13-invoice-note"><b>Territory numbering:</b> this invoice sequence belongs to ${rc13Safe(rc11TerritoryLabel(v.territoryId))}; another territory uses its own numbering sequence.</div></section><section class="rc13-invoice-page"><header><div><small>SYSTEM & INSTALLATION PLANNING</small><h2>${rc13Safe(systemName)}</h2></div><div class="invoice-brand"><b>Page 2 / 2</b><span>Educational project summary</span></div></header><div class="rc13-invoice-visual-grid"><div>${rc13SystemVisual(systemId,systemName)}</div><div><h3>System layers / sequence</h3><ol>${layers||'<li>Layer sequence to be validated from the current system technical documentation.</li>'}</ol></div></div><h3>Project comments & points to plan</h3><p>${rc13Safe(o.comment||o.siteNotes||'No specific project comment recorded.')}</p><ul>${check.map(x=>`<li>${rc13Safe(x)}</li>`).join('')}</ul><div class="rc11-security-banner"><b>Technical validation:</b> quantities and coverage are planning values from the calculator/order. Confirm current manufacturer data, substrate diagnostics, preparation and application conditions before installation.</div></section><div class="toolbar rc11-no-print"><button class="btn secondary" onclick="closeModal()">Close</button><button class="btn primary" onclick="window.print()">Print / Save PDF — max 2 pages</button></div></article>`)}

