function rc13OpenAdminPreRegistration(){const territories=rc13RegistrationTerritories();showModal(`<div class="rc11-modal-wide"><h3>Regional administrator pre-registration</h3><p>Select the actual operating territory. Caribbean territories and Indiana HQ cannot be claimed here. Once submitted, the territory is locked and removed from the available list. USA HQ or Saint-Martin Caribbean HQ may correct the assignment later.</p><div class="rc12-modal-grid"><div class="field"><label>Company</label><input id="rc13RCompany"></div><div class="field"><label>Full name</label><input id="rc13RName"></div><div class="field"><label>Email</label><input id="rc13REmail" type="email"></div><div class="field"><label>Phone</label><input id="rc13RPhone"></div><div class="field"><label>Territory / country / state</label><select id="rc13RTerritory">${territories.map(t=>`<option value="${t.id}">${rc13Safe(rc11RegionName(t.regionId))} · ${rc13Safe(t.name)}${t.city?` — ${rc13Safe(t.city)}`:''}</option>`).join('')}</select></div><div class="field"><label>Password</label><input id="rc13RPassword" type="password"></div><div class="field full"><label>Notes / role</label><textarea id="rc13RNotes" rows="3"></textarea></div></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc13RSubmit" ${territories.length?'':'disabled'}>Submit pre-registration</button></div></div>`);$('rc13RSubmit')?.addEventListener('click',async()=>{const territory=$('rc13RTerritory').value,t=rc11Territory(territory),name=$('rc13RName').value.trim(),email=$('rc13REmail').value.trim().toLowerCase(),pw=$('rc13RPassword').value;if(!t||!name||!email||pw.length<8)return toast('Territory, name, email and an 8+ character password are required.');if(rc13TerritoryClaimed(territory)||store.accounts.some(x=>x.email?.toLowerCase()===email))return toast('Territory or email is no longer available.');const id=rc11SafeId('admin-pending'),profile={id,name,email,company:$('rc13RCompany').value.trim()||'Regional partner',phone:$('rc13RPhone').value.trim(),level:'regional_admin',departmentId:'sales',regionId:t.regionId,territoryId:t.id,active:false,status:'pending',protected:false,territoryLocked:true,notes:$('rc13RNotes').value.trim(),createdAt:new Date().toISOString(),permissions:{manageProfessionals:true,manageAdmins:false,managePricing:true,globalAnalytics:false,manageExternalInvoices:true}};store.adminProfiles.push(profile);store.accounts.push({id:rc11SafeId('admin-account'),role:'admin',company:profile.company,contact:name,email,passwordHash:await hashText(pw),active:false,adminProfileId:id,regionId:t.regionId,territoryId:t.id,createdAt:new Date().toISOString(),preRegistered:true});rc13Settings().registrationReservations[t.id]={adminId:id,createdAt:new Date().toISOString()};saveStore();closeModal();toast('Pre-registration submitted. The territory is now reserved pending HQ approval.')})}
function rc13OpenProfessionalPreRegistration(){const s=rc13Settings(),territories=rc11Territories().filter(t=>t.regionId!=='CARIBBEAN'||s.allowCaribbeanProfessionalSelfRegistration);showModal(`<div class="rc11-modal-wide"><h3>Professional pre-registration</h3><p>Caribbean self-registration is available only when Saint-Martin Caribbean HQ enables it. All self-registered professional accounts require regional approval before login.</p><div class="rc12-modal-grid"><div class="field"><label>Company</label><input id="rc13PRCompany"></div><div class="field"><label>First name</label><input id="rc13PRFirst"></div><div class="field"><label>Last name</label><input id="rc13PRLast"></div><div class="field"><label>Client type</label><select id="rc13PRType">${rc13ClientTypeOptions('Subcontractor / Applicator')}</select></div><div class="field"><label>Email</label><input id="rc13PREmail" type="email"></div><div class="field"><label>Phone</label><input id="rc13PRPhone"></div><div class="field"><label>Territory</label><select id="rc13PRTerritory">${territories.map(t=>`<option value="${t.id}">${rc13Safe(rc11RegionName(t.regionId))} · ${rc13Safe(t.name)}</option>`).join('')}</select></div><div class="field"><label>Password</label><input id="rc13PRPassword" type="password"></div></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc13PRSubmit">Submit</button></div></div>`);$('rc13PRSubmit').onclick=async()=>{const t=rc11Territory($('rc13PRTerritory').value),company=$('rc13PRCompany').value.trim(),first=$('rc13PRFirst').value.trim(),last=$('rc13PRLast').value.trim(),email=$('rc13PREmail').value.trim().toLowerCase(),pw=$('rc13PRPassword').value;if(!t||!company||!first||!last||!email||pw.length<8)return toast('Complete all required fields and use an 8+ character password.');if(t.regionId==='CARIBBEAN'&&!rc13Settings().allowCaribbeanProfessionalSelfRegistration)return toast('Caribbean self-registration is disabled by Saint-Martin HQ.');if(store.accounts.some(x=>x.email?.toLowerCase()===email))return toast('Email already exists.');const id=rc11SafeId('client-pending');store.accounts.push({id,role:'client',company,legalName:company,firstName:first,lastName:last,contact:`${first} ${last}`,clientType:$('rc13PRType').value,email,phone:$('rc13PRPhone').value.trim(),passwordHash:await hashText(pw),active:false,status:'pending',regionId:t.regionId,territoryId:t.id,country:t.name,city:t.city||'',priceTier:'recommended',catalogAccess:false,createdAt:new Date().toISOString()});store.tenants[id]={cart:[],simulations:[],orders:[],documents:[],productChoices:{},packChoices:{},lineOverrides:{},customLines:{},visualSelection:null,messages:[],notifications:[]};saveStore();closeModal();toast('Professional pre-registration submitted for regional approval.')}}
