/* ================= RENOVO CRETE V14 — ACCOUNT GOVERNANCE & PROFESSIONAL ENABLEMENT ================= */
const RC14_VERSION='V14 ACCOUNT GOVERNANCE & ENABLEMENT';
const RC14_DOC_TYPES={identity:'Government ID / identity document',address:'Proof of address',business:'Kbis / business registration / micro-enterprise proof',portrait:'Professional profile photo'};
const RC14_DEPARTMENTS=['Commercial & Sales','Marketing & Communication','Technical / Project Management','Accounting & Finance','Training & Academy','Health, Safety & Compliance','Operations & Logistics','Events & Community','IT & Digital'];
function rc14Settings(){
 const s=rc13Settings();
 s.transactionalEmail=s.transactionalEmail||{proxyUrl:'',fromName:'RENOVO CRETE',replyTo:''};
 s.profileDocuments=Array.isArray(s.profileDocuments)?s.profileDocuments:[];
 s.documentationLibrary=Array.isArray(s.documentationLibrary)?s.documentationLibrary:[];
 s.events=Array.isArray(s.events)?s.events:[];
 s.productOrderEmailByScope=s.productOrderEmailByScope||{};
 s.approvalHistory=Array.isArray(s.approvalHistory)?s.approvalHistory:[];
 s.v14Initialized=!!s.v14Initialized;
 if(!s.v14Initialized){s.allowCaribbeanProfessionalSelfRegistration=true;s.v14Initialized=true}
 return s;
}
function rc14ScopeKeyForClient(c){return c?.regionId==='CARIBBEAN'?'REGION:CARIBBEAN':`TERRITORY:${c?.territoryId||''}`}
function rc14CanManageWorld(p=rc11AdminProfile()){return rc12IsWorldHq(p)||rc12IsCaribbeanHq(p)}
function rc14CanApproveRegionalAdmin(p=rc11AdminProfile()){return rc12IsWorldHq(p)||rc12IsCaribbeanHq(p)}
function rc14CanApproveProfessional(c,p=rc11AdminProfile()){
 if(!c||!p)return false;if(rc12IsWorldHq(p)||rc12IsCaribbeanHq(p))return true;
 return p.level==='regional_admin'&&(c.territoryId===p.territoryId||(p.extraTerritoryIds||[]).includes(c.territoryId)||(p.extraRegionIds||[]).includes(c.regionId));
}
function rc14ProfileDocs(accountId){return rc14Settings().profileDocuments.filter(d=>d.accountId===accountId&&!d.deletedAt)}
function rc14UniqueEmail(email,exceptId=''){return !(store.accounts||[]).some(a=>a.id!==exceptId&&String(a.email||'').toLowerCase()===String(email||'').trim().toLowerCase())}
function rc14PendingAdmins(){return (store.adminProfiles||[]).filter(a=>a.status==='pending'||a.active===false&&a.preRegistered)}
function rc14PendingPros(){return (store.accounts||[]).filter(a=>a.role==='client'&&(a.status==='pending'||a.active===false&&a.preRegistered))}
function rc14TerritoryLabelForRegion(regionId){return regionId==='USA'?'State / territory':regionId==='CARIBBEAN'?'Island / territory':'Country / territory'}
function rc14AvailableAdminTerritories(regionId){return rc11Territories(regionId).filter(t=>t.id!=='usa-indiana-hq'&&t.regionId!=='CARIBBEAN'&&!rc13TerritoryClaimed(t.id))}
function rc14ProfessionalTerritories(regionId){return rc11Territories(regionId)}
function rc14RegionOptions(selected='',includeCaribbean=true){return RC11_REGION_SEED.filter(r=>includeCaribbean||r.id!=='CARIBBEAN').map(r=>`<option value="${rc13Safe(r.id)}" ${r.id===selected?'selected':''}>${r.flag||''} ${rc13Safe(rc11RegionName(r.id))}</option>`).join('')}
function rc14TerritoryOptions(regionId,selected='',mode='professional'){const ts=mode==='admin'?rc14AvailableAdminTerritories(regionId):rc14ProfessionalTerritories(regionId);return ts.map(t=>`<option value="${rc13Safe(t.id)}" ${t.id===selected?'selected':''}>${rc13Safe(t.name)}${t.city?` — ${rc13Safe(t.city)}`:''}</option>`).join('')}

/* IndexedDB document store: bytes remain local in this HTML prototype. */
function rc14OpenDocDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open('renovo-crete-v14-documents',1);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains('files'))db.createObjectStore('files',{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function rc14SaveBlob(id,blob){const db=await rc14OpenDocDb();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put({id,blob});tx.oncomplete=()=>{db.close();resolve(true)};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function rc14LoadBlob(id){const db=await rc14OpenDocDb();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readonly'),r=tx.objectStore('files').get(id);r.onsuccess=()=>{db.close();resolve(r.result?.blob||null)};r.onerror=()=>{db.close();reject(r.error)}})}
async function rc14StoreProfileDocument(accountId,type,file){if(!file)return null;const id=rc11SafeId('profile-doc');await rc14SaveBlob(id,file);const meta={id,accountId,type,name:file.name||RC14_DOC_TYPES[type]||'Document',mimeType:file.type||'',size:file.size||0,createdAt:new Date().toISOString(),uploadedBy:currentAccount()?.email||'pre-registration'};rc14Settings().profileDocuments.unshift(meta);return meta}
async function rc14OpenProfileDocument(id){try{const b=await rc14LoadBlob(id);if(!b)return toast('Document file is not available on this device.');const u=URL.createObjectURL(b);window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),60000)}catch(e){toast('Unable to open this local document.')}}
function rc14ProfileDocRows(accountId,canDelete=false){const ds=rc14ProfileDocs(accountId);return ds.length?`<div class="rc14-doc-list">${ds.map(d=>`<div class="rc14-doc-row"><span><b>${rc13Safe(RC14_DOC_TYPES[d.type]||d.type)}</b><br><small>${rc13Safe(d.name)} · ${rc11Date(d.createdAt,true)}</small></span><span><button class="btn secondary small" data-rc14-open-doc="${d.id}">Open</button>${canDelete?` <button class="btn danger small" data-rc14-delete-doc="${d.id}">Delete</button>`:''}</span></div>`).join('')}</div>`:'<div class="rc12-empty">No identity/company document uploaded yet.</div>'}

/* Credential issue/send. Plaintext passwords are never persisted; only the hash is saved. */
function rc14CredentialEmail(c,password,kind='professional'){const subject=`RENOVO CRETE — Your ${kind} portal access`;const body=`Welcome ${rcClientName(c)||c.contact||c.company||''},\n\nYour RENOVO CRETE portal access has been prepared.\n\nLogin / email: ${c.email}\nTemporary password: ${password}\n\nPlease sign in and change/secure your credentials as soon as the production authentication service is enabled.\n\nRENOVO CRETE`;return{subject,body}}
async function rc14DeliverEmail(to,subject,body){const cfg=rc14Settings().transactionalEmail;if(cfg.proxyUrl){const r=await fetch(cfg.proxyUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({to,subject,body,fromName:cfg.fromName,replyTo:cfg.replyTo||''})});if(!r.ok)throw new Error('email');return 'sent'}location.href=`mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;return 'draft'}
async function rc14IssueCredential(clientId,send=true){const c=(store.accounts||[]).find(x=>x.id===clientId&&x.role==='client');if(!c||!rc11CanManageClient(c))return toast('No permission.');if(!c.email)return toast('Email is required before credentials can be issued.');const pw=rc12GeneratePassword();c.passwordHash=await hashText(pw);c.loginPending=false;c.lastCredentialIssuedAt=new Date().toISOString();if(c.status!=='pending'){c.active=true;c.status='approved'}saveStore();const m=rc14CredentialEmail(c,pw,'professional');if(send){try{const mode=await rc14DeliverEmail(c.email,m.subject,m.body);toast(mode==='sent'?'Credentials sent through the secure email connector.':'Email draft prepared with new credentials.')}catch(e){toast('Credential updated, but the secure email connector failed.')}}return{c,pw,...m}}
function rc14ConfirmCredential(clientId){const c=(store.accounts||[]).find(x=>x.id===clientId);if(!c)return;showModal(`<div class="rc11-modal-wide"><h3>Send new login credentials?</h3><p><b>${rc13Safe(c.company)}</b><br>Login ID: ${rc13Safe(c.email||'No email')}</p><div class="notice warn"><b>Security:</b> a new temporary password will be generated. The old password will stop working. The plaintext password is not saved in this HTML file.</div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc14ConfirmCredentialSend">Generate & send</button></div></div>`);$('rc14ConfirmCredentialSend').onclick=async()=>{closeModal();await rc14IssueCredential(clientId,true)}}
async function rc14BulkCredentials(ids){const list=[...new Set(ids)].map(id=>(store.accounts||[]).find(c=>c.id===id&&c.role==='client')).filter(c=>c&&rc11CanManageClient(c)&&c.email);if(!list.length)return toast('Select at least one manageable professional.');const useProxy=!!rc14Settings().transactionalEmail.proxyUrl;const out=[];for(const c of list){const pw=rc12GeneratePassword();c.passwordHash=await hashText(pw);c.loginPending=false;c.lastCredentialIssuedAt=new Date().toISOString();if(c.status!=='pending'){c.active=true;c.status='approved'}const m=rc14CredentialEmail(c,pw,'professional');let delivery='prepared';if(useProxy){try{await rc14DeliverEmail(c.email,m.subject,m.body);delivery='sent'}catch(e){delivery='failed'}}out.push({company:c.company,email:c.email,password:pw,delivery})}saveStore();if(useProxy){toast(`${out.filter(x=>x.delivery==='sent').length}/${out.length} credential email(s) sent.`)}else{const csv=['Company,Email,Temporary password,Delivery',...out.map(x=>[x.company,x.email,x.password,x.delivery].map(v=>'"'+String(v||'').replace(/"/g,'""')+'"').join(','))].join('\n');rc14DownloadText(`RENOVO_CRETE_Credentials_${new Date().toISOString().slice(0,10)}.csv`,csv,'text/csv');showModal(`<h3>${out.length} credentials prepared</h3><p>A CSV was generated because no secure transactional-email proxy is configured. For automatic bulk sending, configure the connector in Administration → Settings.</p><div class="toolbar"><button class="btn primary" onclick="closeModal()">Close</button></div>`)} }
function rc14DownloadText(name,text,type='text/plain'){const b=new Blob([text],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}

/* Smarter pre-registration with hierarchical Region -> State/Country/Territory selection and required documents. */
function rc14PreRegFiles(prefix){return{identity:$(prefix+'Identity')?.files?.[0],address:$(prefix+'AddressDoc')?.files?.[0],business:$(prefix+'BusinessDoc')?.files?.[0],portrait:$(prefix+'Portrait')?.files?.[0]}}
function rc14PreRegFileFields(prefix){return`<div class="rc14-file-field"><label>Government ID *</label><input id="${prefix}Identity" type="file" accept="image/*,.pdf" capture="environment"><small>Upload a file or take a photo from the phone.</small></div><div class="rc14-file-field"><label>Proof of address *</label><input id="${prefix}AddressDoc" type="file" accept="image/*,.pdf" capture="environment"><small>Utility bill, official proof, etc.</small></div><div class="rc14-file-field"><label>Kbis / business registration / micro-enterprise proof *</label><input id="${prefix}BusinessDoc" type="file" accept="image/*,.pdf" capture="environment"><small>Company/legal-business evidence.</small></div><div class="rc14-file-field"><label>Professional photo *</label><input id="${prefix}Portrait" type="file" accept="image/*" capture="user"><small>Camera or photo library.</small></div>`}
function rc14OpenAdminPreRegistration(){const regions=RC11_REGION_SEED.filter(r=>r.id!=='CARIBBEAN'),initial=regions.find(r=>r.id==='USA')?.id||regions[0]?.id||'';showModal(`<div class="rc11-modal-wide"><h3>Regional administrator pre-registration</h3><p>Choose the operating region first. The second list automatically shows only the available state/country/territory. Caribbean territories are reserved for Saint-Martin Caribbean HQ and Indiana is reserved for USA HQ. Once a regional territory is reserved, it disappears from new administrator registrations until HQ rejects/releases it.</p><div class="rc12-modal-grid"><div class="field"><label>Company / organization</label><input id="rc14RACompany"></div><div class="field"><label>Full name</label><input id="rc14RAName"></div><div class="field"><label>Email / login ID</label><input id="rc14RAEmail" type="email"></div><div class="field"><label>Phone</label><input id="rc14RAPhone"></div><div class="rc14-location-picker full"><div class="field"><label>Region</label><select id="rc14RARegion">${rc14RegionOptions(initial,false)}</select></div><div class="field"><label id="rc14RATerritoryLabel">${rc14TerritoryLabelForRegion(initial)}</label><select id="rc14RATerritory">${rc14TerritoryOptions(initial,'','admin')}</select></div><div class="rc14-location-note">Only currently available territories are shown. Assignment is locked after submission and can later be corrected only by USA HQ or Caribbean HQ.</div></div><div class="field"><label>Password</label><input id="rc14RAPassword" type="password" autocomplete="new-password"></div><div class="field"><label>Job title / role</label><input id="rc14RARole"></div><div class="field full"><label>Notes</label><textarea id="rc14RANotes" rows="3"></textarea></div></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc14RASubmit">Submit for HQ approval</button></div></div>`);const sync=()=>{const rid=$('rc14RARegion').value;$('rc14RATerritoryLabel').textContent=rc14TerritoryLabelForRegion(rid);$('rc14RATerritory').innerHTML=rc14TerritoryOptions(rid,'','admin');$('rc14RASubmit').disabled=!$('rc14RATerritory').value};$('rc14RARegion').onchange=sync;sync();$('rc14RASubmit').onclick=async()=>{const t=rc11Territory($('rc14RATerritory').value),name=$('rc14RAName').value.trim(),email=$('rc14RAEmail').value.trim().toLowerCase(),pw=$('rc14RAPassword').value;if(!t||!name||!email||pw.length<8)return toast('Complete territory, name, email and an 8+ character password.');if(!rc14UniqueEmail(email)||rc13TerritoryClaimed(t.id))return toast('Email or territory is no longer available.');const id=rc11SafeId('admin-pending'),profile={id,name,email,company:$('rc14RACompany').value.trim()||'Regional partner',phone:$('rc14RAPhone').value.trim(),jobTitle:$('rc14RARole').value.trim(),level:'regional_admin',departmentId:'sales',regionId:t.regionId,territoryId:t.id,active:false,status:'pending',preRegistered:true,protected:false,territoryLocked:true,notes:$('rc14RANotes').value.trim(),createdAt:new Date().toISOString(),permissions:{manageProfessionals:true,manageAdmins:false,managePricing:true,globalAnalytics:false,manageExternalInvoices:true}};store.adminProfiles.push(profile);store.accounts.push({id:rc11SafeId('admin-account'),role:'admin',company:profile.company,contact:name,email,passwordHash:await hashText(pw),active:false,status:'pending',preRegistered:true,adminProfileId:id,regionId:t.regionId,territoryId:t.id,createdAt:new Date().toISOString()});rc13Settings().registrationReservations[t.id]={adminId:id,createdAt:new Date().toISOString()};saveStore();closeModal();toast('Regional administrator pre-registration submitted. HQ approval is required before login.')}}
function rc14OpenProfessionalPreRegistration(){const initial='CARIBBEAN';showModal(`<div class="rc11-modal-wide"><h3>Professional pre-registration</h3><p>Create a contractor/applicator/architect/professional file. Access remains blocked until the appropriate HQ or regional administrator validates the application.</p><div class="rc12-modal-grid"><div class="field"><label>Company / trading name</label><input id="rc14RPCompany"></div><div class="field"><label>Legal name</label><input id="rc14RPLegal"></div><div class="field"><label>First name</label><input id="rc14RPFirst"></div><div class="field"><label>Last name</label><input id="rc14RPLast"></div><div class="field"><label>Exact professional type</label><select id="rc14RPType">${rc13ClientTypeOptions('Subcontractor / Applicator')}</select></div><div class="field"><label>Email / login ID</label><input id="rc14RPEmail" type="email"></div><div class="field"><label>Phone</label><input id="rc14RPPhone"></div><div class="field"><label>Registration / SIRET / company number</label><input id="rc14RPRegistration"></div><div class="field"><label>Address</label><input id="rc14RPAddress"></div><div class="field"><label>Postal code</label><input id="rc14RPPostal"></div><div class="rc14-location-picker full"><div class="field"><label>Region</label><select id="rc14RPRegion">${rc14RegionOptions(initial,true)}</select></div><div class="field"><label id="rc14RPTerritoryLabel">${rc14TerritoryLabelForRegion(initial)}</label><select id="rc14RPTerritory">${rc14TerritoryOptions(initial,'','professional')}</select></div><div class="rc14-location-note">The list is live: territories added or removed by an authorized HQ automatically appear/disappear here. Caribbean professional registration is governed by Saint-Martin Caribbean HQ.</div></div><div class="field"><label>Password</label><input id="rc14RPPassword" type="password" autocomplete="new-password"></div>${rc14PreRegFileFields('rc14RP')}</div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc14RPSubmit">Submit professional application</button></div></div>`);const sync=()=>{const rid=$('rc14RPRegion').value;$('rc14RPTerritoryLabel').textContent=rc14TerritoryLabelForRegion(rid);$('rc14RPTerritory').innerHTML=rc14TerritoryOptions(rid,'','professional')};$('rc14RPRegion').onchange=sync;sync();$('rc14RPSubmit').onclick=async()=>{const t=rc11Territory($('rc14RPTerritory').value),company=$('rc14RPCompany').value.trim(),first=$('rc14RPFirst').value.trim(),last=$('rc14RPLast').value.trim(),email=$('rc14RPEmail').value.trim().toLowerCase(),pw=$('rc14RPPassword').value,files=rc14PreRegFiles('rc14RP');if(!t||!company||!first||!last||!email||pw.length<8)return toast('Complete all required identity fields and use an 8+ character password.');if(t.regionId==='CARIBBEAN'&&!rc14Settings().allowCaribbeanProfessionalSelfRegistration)return toast('Caribbean professional self-registration is currently disabled by Saint-Martin HQ.');if(!Object.values(files).every(Boolean))return toast('Government ID, proof of address, business registration and professional photo are required.');if(!rc14UniqueEmail(email))return toast('Email already exists.');const id=rc11SafeId('client-pending');store.accounts.push({id,role:'client',company,legalName:$('rc14RPLegal').value.trim()||company,firstName:first,lastName:last,contact:`${first} ${last}`,clientType:$('rc14RPType').value,email,phone:$('rc14RPPhone').value.trim(),registrationNumber:$('rc14RPRegistration').value.trim(),siret:$('rc14RPRegistration').value.trim(),address1:$('rc14RPAddress').value.trim(),postalCode:$('rc14RPPostal').value.trim(),passwordHash:await hashText(pw),active:false,status:'pending',preRegistered:true,regionId:t.regionId,territoryId:t.id,country:t.name,city:t.city||'',priceTier:'recommended',catalogAccess:false,createdAt:new Date().toISOString()});store.tenants[id]={cart:[],simulations:[],orders:[],documents:[],productChoices:{},packChoices:{},lineOverrides:{},customLines:{},visualSelection:null,messages:[],notifications:[],docProgress:{}};for(const[k,f]of Object.entries(files))await rc14StoreProfileDocument(id,k,f);saveStore();closeModal();toast('Professional pre-registration submitted. Approval is required before login.')}}

/* Professional CRM list with intelligent multi-selection and credential actions. */
function rc14ProfessionalCard(c,index){const s=rcClientStats(c),can=rc11CanManageClient(c);return`<article class="rc11-entity-card" data-rc11-professional data-search="${rc13Safe(rc13ProfessionalSearchData(c))}" data-region="${rc13Safe(c.regionId)}" data-territory="${rc13Safe(c.territoryId)}" data-tier="${rc13Safe(rcTierFor(s.net))}" data-active="${c.active?'yes':'no'}" data-client-type="${rc13Safe(c.clientType||'')}" data-status="${rc13Safe(c.status||'approved')}"><span class="rc11-number">${String(index+1).padStart(3,'0')}</span><div class="rc11-card-body"><label class="rc14-select"><input type="checkbox" data-rc14-select-pro="${rc13Safe(c.id)}"> Select</label><div class="head"><div><h3>${rc13Safe(c.company||'—')}</h3><p>${rc13Safe(rcClientName(c))} · ${rc13Safe(c.clientType||'Professional')}</p></div><span class="rc11-status ${c.active?'ok':c.status==='pending'?'warn':'danger'}">${rc13Safe(c.status==='pending'?'Pending approval':c.active?'Active':'Inactive')}</span></div><div class="meta"><span>${rc13Safe(c.email||'No email')}</span><span>${rc13Safe(rc11RegionName(c.regionId))}</span><span>${rc13Safe(rc11TerritoryLabel(c.territoryId))}</span><span>${rc13Safe(c.registrationNumber||c.siret||'Registration no. not set')}</span></div><div class="rc11-region-stats"><div><small>Orders</small><b>${s.orders.length}</b></div><div><small>Purchases</small><b>${rc11Money(s.net)}</b></div><div><small>Outstanding</small><b>${rc11Money(s.balance)}</b></div></div><div class="toolbar"><button class="btn primary small" data-rc13-client-sheet="${rc13Safe(c.id)}">Full profile</button>${can?`<button class="btn secondary small" data-rc11-edit-client="${rc13Safe(c.id)}">Edit</button><button class="btn secondary small" data-rc13-open-client="${rc13Safe(c.id)}">Open portal</button><button class="btn dark small" data-rc14-credential="${rc13Safe(c.id)}">Send credentials</button>`:'<span class="rc11-status">Read only</span>'}</div><div class="rc14-credential-status ${c.lastCredentialIssuedAt?'ok':''}">${c.lastCredentialIssuedAt?`Credentials last generated ${rc11Date(c.lastCredentialIssuedAt,true)}`:'No credential email generated yet'}</div></div></article>`}
renderClients=function(){const clients=rc11VisibleClients().sort((a,b)=>String(a.company).localeCompare(String(b.company))),regions=[...new Set(clients.map(c=>c.regionId))],types=[...new Set(clients.map(c=>c.clientType).filter(Boolean))].sort(),mode=rc11Settings().viewModes.professionals||'medium';return rc11Hero('Professionals & partners','Filter, review, edit and grant portal access to subcontractors, applicators, architects and other professional profiles.','CRM & ACCESS',`<button class="btn primary" id="rc11AddProfessional">Add professional</button>`,[`${clients.length} professionals`])+rc11AccessNote()+`<div class="rc14-toolbar"><div class="field"><label>Search</label><input id="rc11ProfessionalSearch" placeholder="Name, company, email, registration"></div><div class="field"><label>Region</label><select id="rc11ProfessionalRegion"><option value="">All</option>${regions.map(id=>`<option value="${id}">${rc13Safe(rc11RegionName(id))}</option>`).join('')}</select></div><div class="field"><label>Territory</label><select id="rc11ProfessionalTerritory"><option value="">All</option>${rc11Territories().filter(t=>clients.some(c=>c.territoryId===t.id)).map(t=>`<option value="${t.id}">${rc13Safe(t.name)}</option>`).join('')}</select></div><div class="field"><label>Professional type</label><select id="rc14ProfessionalType"><option value="">All</option>${types.map(x=>`<option>${rc13Safe(x)}</option>`).join('')}</select></div><div class="field"><label>Status</label><select id="rc11ProfessionalActive"><option value="">All</option><option value="yes">Active</option><option value="no">Inactive</option><option value="pending">Pending approval</option></select></div><div class="field"><label>View</label>${rc11ViewSwitch('professionals')}</div></div><div class="rc14-toolbar"><button class="btn secondary" id="rc14SelectFilteredPros">Select filtered</button><button class="btn secondary" id="rc14ClearPros">Clear selection</button><button class="btn primary" id="rc14BulkCredentials">Generate / send credentials to selected</button><span class="rc12-mini-note">Automatic bulk email requires the secure transactional-email connector. Without it, a credential CSV is generated.</span></div><div class="rc11-entity-list" id="rc11ProfessionalList" data-view-mode="${mode}">${clients.map(rc14ProfessionalCard).join('')||'<div class="rc11-empty">No professional.</div>'}</div><div class="hidden" aria-hidden="true"><button id="newClient" type="button"></button></div>`}
function rc14ApplyProfessionalFilters(){const q=($('rc11ProfessionalSearch')?.value||'').toLowerCase(),r=$('rc11ProfessionalRegion')?.value||'',t=$('rc11ProfessionalTerritory')?.value||'',type=$('rc14ProfessionalType')?.value||'',status=$('rc11ProfessionalActive')?.value||'';document.querySelectorAll('[data-rc11-professional]').forEach(el=>{const active=el.dataset.active,st=el.dataset.status;const ok=(!q||el.dataset.search.includes(q))&&(!r||el.dataset.region===r)&&(!t||el.dataset.territory===t)&&(!type||el.dataset.clientType===type)&&(!status||(status==='pending'?st==='pending':active===status));el.style.display=ok?'':'none'})}

/* Rich admin-facing professional dossier: documents + credential issue + portal access. */
rc13OpenProfessionalSheet=function(id){const c=(store.accounts||[]).find(x=>x.id===id&&x.role==='client');if(!c||!rc11CanSeeClient(c))return toast('No permission.');const s=rcClientStats(c),t=store.tenants[c.id]||{},can=rc11CanManageClient(c),orders=(t.orders||[]).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));showModal(`<div class="rc11-modal-wide rc13-profile-sheet"><div class="rc13-profile-head"><div><span class="eyebrow">PROFESSIONAL DOSSIER</span><h2>${rc13Safe(c.company)}</h2><p>${rc13Safe(rcClientName(c))} · ${rc13Safe(c.clientType||'Professional')}</p></div><span class="rc11-status ${c.status==='pending'?'warn':c.active?'ok':'danger'}">${rc13Safe(c.status==='pending'?'Pending approval':c.active?'Active':'Inactive')}</span></div><div class="rc13-profile-grid"><section><h4>Identity & company</h4><p><b>Legal name:</b> ${rc13Safe(c.legalName||c.company||'—')}<br><b>Registration / SIRET / SIREN:</b> ${rc13Safe(c.registrationNumber||c.siret||'—')}<br><b>VAT / Tax ID:</b> ${rc13Safe(c.vatNumber||'—')}<br><b>Exact type:</b> ${rc13Safe(c.clientType||'—')}<br><b>Business activity:</b> ${rc13Safe(c.businessActivity||'—')}<br><b>Website:</b> ${rc13Safe(c.website||'—')}</p></section><section><h4>Contact & login</h4><p><b>Login ID / email:</b> ${rc13Safe(c.email||'—')}<br><b>Phone:</b> ${rc13Safe(c.phone||'—')}<br><b>Secondary phone:</b> ${rc13Safe(c.secondaryPhone||'—')}<br><b>Job title:</b> ${rc13Safe(c.jobTitle||'—')}<br><b>Language:</b> ${rc13Safe(c.preferredLanguage||'—')}</p></section><section><h4>Address & assignment</h4><p>${rc13Safe(c.address1||'—')}<br>${rc13Safe(c.address2||'')}<br>${rc13Safe([c.postalCode,c.city].filter(Boolean).join(' '))}<br>${rc13Safe(c.country||rc11Territory(c.territoryId)?.name||'')}</p><p><b>Region:</b> ${rc13Safe(rc11RegionName(c.regionId))}<br><b>Territory:</b> ${rc13Safe(rc11TerritoryLabel(c.territoryId))}</p></section><section><h4>CRM & account</h4><p><b>HubSpot ID:</b> ${rc13Safe(c.hubspotId||'—')}<br><b>Acquisition:</b> ${rc13Safe(c.acquisitionSource||'—')}<br><b>Expertise:</b> ${rc13Safe(c.expertiseLevel||'—')}<br><b>Created:</b> ${rc13Safe(rc11Date(c.createdAt,true))}<br><b>Status:</b> ${rc13Safe(c.status||'approved')}</p></section></div><div class="rc11-kpis">${rc11Kpi('Orders',s.orders.length,'')}${rc11Kpi('Purchased',rc11Money(s.net),'')}${rc11Kpi('Collected',rc11Money(s.paid),'','success')}${rc11Kpi('Outstanding',rc11Money(s.balance),'','danger')}</div><section class="rc13-notes"><h4>Identity / company documents</h4>${rc14ProfileDocRows(c.id,false)}</section><section class="rc13-notes"><h4>Internal notes</h4><p>${rc13Safe(c.notes||'No internal notes.')}</p></section><h4>Recent orders</h4><div class="table-wrap"><table class="rc11-table"><thead><tr><th>Order</th><th>Date</th><th>System</th><th>Total</th><th>Payment</th></tr></thead><tbody>${orders.slice(0,10).map(o=>`<tr><td>${rc13Safe(rc11OrderDisplay(o))}</td><td>${rc13Safe(rc11Date(o.createdAt))}</td><td>${rc13Safe(o.systemName||rcSystemKey(o))}</td><td>${rc11Money(o.totalEUR)}</td><td>${rc13Safe(o.paymentStatus||'')}</td></tr>`).join('')||'<tr><td colspan="5">No order.</td></tr>'}</tbody></table></div><div class="toolbar">${can?`<button class="btn primary" data-rc13-edit-client-modal="${rc13Safe(c.id)}">Edit profile</button><button class="btn dark" data-rc13-open-client="${rc13Safe(c.id)}">Open professional portal</button><button class="btn secondary" data-rc14-credential="${rc13Safe(c.id)}">Generate & send new login</button>`:''}${c.status==='pending'&&rc14CanApproveProfessional(c)?`<button class="btn primary" data-rc14-approve-pro="${rc13Safe(c.id)}">Approve registration</button>`:''}<a class="btn secondary" href="mailto:${encodeURIComponent(c.email||'')}">Email</a><a class="btn secondary" href="tel:${rc13Safe(c.phone||'')}">Call</a><button class="btn secondary" onclick="closeModal()">Close</button></div></div>`)}

/* Professional self profile and files. */
function renderProfessionalProfileV14(){const c=currentClient();if(!c)return'';return rc11Hero('My professional profile','Review and update your professional/company information. Your login email identifies your account and is protected from self-service changes.','MY PROFILE','',[`${rc13Safe(rc11RegionName(c.regionId))} · ${rc13Safe(rc11Territory(c.territoryId)?.name||'')}`])+`<div class="rc14-profile-banner"><div><h2>${rc13Safe(c.company)}</h2><p>${rc13Safe(rcClientName(c))} · ${rc13Safe(c.clientType||'Professional')}</p></div><span class="rc14-identity-badge">Login: ${rc13Safe(c.email)}</span></div><section class="rc11-panel"><div class="rc12-modal-grid"><div class="field"><label>Company / trading name</label><input id="rc14PFCompany" value="${rc13Safe(c.company||'')}"></div><div class="field"><label>Legal name</label><input id="rc14PFLegal" value="${rc13Safe(c.legalName||'')}"></div><div class="field"><label>First name</label><input id="rc14PFFirst" value="${rc13Safe(c.firstName||'')}"></div><div class="field"><label>Last name</label><input id="rc14PFLast" value="${rc13Safe(c.lastName||'')}"></div><div class="field"><label>Email / login ID</label><input value="${rc13Safe(c.email||'')}" disabled></div><div class="field"><label>Phone</label><input id="rc14PFPhone" value="${rc13Safe(c.phone||'')}"></div><div class="field"><label>Secondary phone</label><input id="rc14PFPhone2" value="${rc13Safe(c.secondaryPhone||'')}"></div><div class="field"><label>Registration / SIRET / SIREN</label><input id="rc14PFRegistration" value="${rc13Safe(c.registrationNumber||c.siret||'')}"></div><div class="field"><label>VAT / Tax ID</label><input id="rc14PFVAT" value="${rc13Safe(c.vatNumber||'')}"></div><div class="field"><label>Job title</label><input id="rc14PFJob" value="${rc13Safe(c.jobTitle||'')}"></div><div class="field full"><label>Address</label><input id="rc14PFAddress1" value="${rc13Safe(c.address1||'')}"></div><div class="field"><label>Address line 2</label><input id="rc14PFAddress2" value="${rc13Safe(c.address2||'')}"></div><div class="field"><label>Postal code</label><input id="rc14PFPostal" value="${rc13Safe(c.postalCode||'')}"></div><div class="field"><label>City</label><input id="rc14PFCity" value="${rc13Safe(c.city||'')}"></div><div class="field"><label>Website</label><input id="rc14PFWebsite" value="${rc13Safe(c.website||'')}"></div><div class="field"><label>Preferred language</label><select id="rc14PFLang"><option value="en" ${c.preferredLanguage==='en'?'selected':''}>English</option><option value="fr" ${c.preferredLanguage==='fr'?'selected':''}>French</option><option value="es" ${c.preferredLanguage==='es'?'selected':''}>Spanish</option></select></div></div><div class="toolbar"><button class="btn primary" id="rc14PFSave">Save profile changes</button></div></section><section class="rc11-panel" style="margin-top:14px"><div class="rc11-section-head"><div><span class="eyebrow">DOCUMENTS</span><h3>My identity & company documents</h3><p>Administrators with access to your regional profile can review these documents.</p></div></div>${rc14ProfileDocRows(c.id,true)}<div class="rc14-doc-grid" style="margin-top:12px">${Object.entries(RC14_DOC_TYPES).map(([k,label])=>`<div class="rc14-file-field"><label>${rc13Safe(label)}</label><input type="file" data-rc14-profile-upload="${k}" accept="image/*,.pdf" ${k==='portrait'?'capture="user"':'capture="environment"'}></div>`).join('')}</div><div class="toolbar"><button class="btn primary" id="rc14PFUploadDocs">Upload selected documents</button></div></section>`}
async function rc14SaveProfessionalProfile(){const c=currentClient();if(!c)return;Object.assign(c,{company:$('rc14PFCompany').value.trim()||c.company,legalName:$('rc14PFLegal').value.trim(),firstName:$('rc14PFFirst').value.trim(),lastName:$('rc14PFLast').value.trim(),contact:`${$('rc14PFFirst').value.trim()} ${$('rc14PFLast').value.trim()}`.trim(),phone:$('rc14PFPhone').value.trim(),secondaryPhone:$('rc14PFPhone2').value.trim(),registrationNumber:$('rc14PFRegistration').value.trim(),siret:$('rc14PFRegistration').value.trim(),vatNumber:$('rc14PFVAT').value.trim(),jobTitle:$('rc14PFJob').value.trim(),address1:$('rc14PFAddress1').value.trim(),address2:$('rc14PFAddress2').value.trim(),postalCode:$('rc14PFPostal').value.trim(),city:$('rc14PFCity').value.trim(),website:$('rc14PFWebsite').value.trim(),preferredLanguage:$('rc14PFLang').value});saveStore();toast('Professional profile updated.');renderShell()}
async function rc14UploadProfessionalDocs(){const c=currentClient();if(!c)return;let n=0;for(const inp of document.querySelectorAll('[data-rc14-profile-upload]')){const f=inp.files?.[0];if(f){await rc14StoreProfileDocument(c.id,inp.dataset.rc14ProfileUpload,f);n++}}saveStore();toast(n?`${n} document(s) uploaded.`:'Select at least one document.');if(n)renderShell()}

/* Documentation access and guided workflows. */
function rc14DocVisibleToClient(d,c){if(!c)return false;if(d.clientIds?.includes(c.id))return true;if(d.territoryIds?.includes(c.territoryId))return true;if(d.regionIds?.includes(c.regionId))return true;return d.audience==='all'}
function renderProfessionalDocumentationV14(){const c=currentClient(),docs=rc14Settings().documentationLibrary.filter(d=>rc14DocVisibleToClient(d,c)),progress=tenantData().docProgress=tenantData().docProgress||{};return rc11Hero('Documentation & guided processes','Your regional administrator controls which documents, videos, links and step-by-step processes are visible to your account.','LEARNING & OPERATIONS','',[`${docs.length} resource(s)`])+`<div class="rc14-doc-grid">${docs.map(d=>`<article class="rc14-doc-card ${d.priority==='High'?'rc14-priority-high':''}"><span class="rc14-dept">${rc13Safe(d.department)}</span><h3>${rc13Safe(d.title)}</h3><p>${rc13Safe(d.description||'')}</p>${d.url?`<a class="btn secondary small" href="${rc13Safe(d.url)}" target="_blank" rel="noopener">Open resource</a>`:''}${d.fileId?`<button class="btn secondary small" data-rc14-open-doc="${d.fileId}">Open file</button>`:''}<div style="margin-top:10px">${(d.steps||[]).map((step,i)=>`<label class="rc14-step"><input type="checkbox" data-rc14-doc-step="${d.id}|${i}" ${progress[d.id]?.[i]?'checked':''}><span><b>Step ${i+1}</b><br>${rc13Safe(step)}</span></label>`).join('')}</div>${d.reminderText?`<div class="notice warn"><b>Reminder</b><br>${rc13Safe(d.reminderText)}</div>`:''}</article>`).join('')||'<div class="rc12-empty">No documentation has been granted to this professional account yet.</div>'}</div>`}
function renderAdminDocumentationV14(){const p=rc11AdminProfile(),docs=rc14Settings().documentationLibrary,regions=rc12AllowedRegions(p);return rc11Hero('Documentation access','Publish commercial, marketing, technical, finance, training, safety and operational resources. Access can be granted globally, by region, territory or individual professional.','DOCUMENTATION GOVERNANCE',`<button class="btn primary" id="rc14AddDocumentation">Add documentation / workflow</button>`,[`${docs.length} resource(s)`])+`<div class="rc14-doc-grid">${docs.map(d=>`<article class="rc14-doc-card ${d.priority==='High'?'rc14-priority-high':''}"><span class="rc14-dept">${rc13Safe(d.department)}</span><h3>${rc13Safe(d.title)}</h3><p>${rc13Safe(d.description||'')}</p><small>Audience: ${rc13Safe(d.audience||'scoped')} · ${rc13Safe((d.regionIds||[]).map(rc11RegionName).join(', ')||(d.territoryIds||[]).map(id=>rc11Territory(id)?.name).join(', ')||(d.clientIds||[]).length+' selected professional(s)')}</small><div class="toolbar">${d.url?`<a class="btn secondary small" href="${rc13Safe(d.url)}" target="_blank" rel="noopener">Open link</a>`:''}${d.fileId?`<button class="btn secondary small" data-rc14-open-doc="${d.fileId}">Open file</button>`:''}<button class="btn danger small" data-rc14-delete-library-doc="${d.id}">Delete</button></div></article>`).join('')||'<div class="rc12-empty">No documentation published yet.</div>'}</div>`}
function rc14OpenAddDocumentation(){const p=rc11AdminProfile(),regions=rc12AllowedRegions(p),clients=rc11VisibleClients();showModal(`<div class="rc11-modal-wide"><h3>Add documentation / guided workflow</h3><div class="rc12-modal-grid"><div class="field"><label>Department</label><select id="rc14DocDept">${RC14_DEPARTMENTS.map(x=>`<option>${rc13Safe(x)}</option>`).join('')}</select></div><div class="field"><label>Priority</label><select id="rc14DocPriority"><option>Normal</option><option>High</option></select></div><div class="field full"><label>Title</label><input id="rc14DocTitle"></div><div class="field full"><label>Description</label><textarea id="rc14DocDesc" rows="3"></textarea></div><div class="field full"><label>YouTube / web link (optional)</label><input id="rc14DocUrl" placeholder="https://..."></div><div class="field full"><label>Upload PDF / image / video (optional)</label><input id="rc14DocFile" type="file" accept=".pdf,image/*,video/*"></div><div class="field full"><label>Workflow steps — one step per line</label><textarea id="rc14DocSteps" rows="5" placeholder="Prepare...\nComplete...\nValidate..."></textarea></div><div class="field full"><label>Reminder / deadline instruction</label><input id="rc14DocReminder" placeholder="Complete this step within 48 hours..."></div><div class="field"><label>Audience type</label><select id="rc14DocAudience"><option value="region">Region</option><option value="territory">Territory</option><option value="client">Selected professional</option><option value="all">All visible professionals</option></select></div><div class="field"><label>Region</label><select id="rc14DocRegion">${regions.map(r=>`<option value="${r}">${rc13Safe(rc11RegionName(r))}</option>`).join('')}</select></div><div class="field"><label>Territory</label><select id="rc14DocTerritory"></select></div><div class="field"><label>Professional</label><select id="rc14DocClient">${clients.map(c=>`<option value="${c.id}">${rc13Safe(c.company)} — ${rc13Safe(rc11Territory(c.territoryId)?.name||'')}</option>`).join('')}</select></div></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc14DocSave">Publish</button></div></div>`);const sync=()=>{$('rc14DocTerritory').innerHTML=rc12AllowedTerritories(p,$('rc14DocRegion').value).map(id=>`<option value="${id}">${rc13Safe(rc11Territory(id)?.name||id)}</option>`).join('')};$('rc14DocRegion').onchange=sync;sync();$('rc14DocSave').onclick=async()=>{const title=$('rc14DocTitle').value.trim();if(!title)return toast('Title required.');const id=rc11SafeId('doclib'),aud=$('rc14DocAudience').value,d={id,department:$('rc14DocDept').value,priority:$('rc14DocPriority').value,title,description:$('rc14DocDesc').value.trim(),url:$('rc14DocUrl').value.trim(),steps:$('rc14DocSteps').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),reminderText:$('rc14DocReminder').value.trim(),audience:aud,regionIds:aud==='region'?[$('rc14DocRegion').value]:[],territoryIds:aud==='territory'?[$('rc14DocTerritory').value]:[],clientIds:aud==='client'?[$('rc14DocClient').value]:[],createdAt:new Date().toISOString(),createdBy:p?.name||''};const f=$('rc14DocFile').files?.[0];if(f){const fid=rc11SafeId('library-file');await rc14SaveBlob(fid,f);d.fileId=fid;d.fileName=f.name}rc14Settings().documentationLibrary.unshift(d);saveStore();closeModal();renderShell();toast('Documentation published.')}}

