function renderProfessionalEventsV14(){const c=currentClient(),events=rc14Settings().events.filter(e=>rc14EventVisible(e,c)).sort((a,b)=>new Date(a.start)-new Date(b.start));return rc11Hero('Events & training calendar','Upcoming trainings, demonstrations, meetings and regional events made available to your account.','CALENDAR','',[`${events.length} event(s)`])+`<div class="rc14-event-grid">${events.map(e=>`<article class="rc14-event-card"><span class="rc14-dept">${rc13Safe(e.type||'Event')}</span><h3>${rc13Safe(e.title)}</h3><p><b>${rc13Safe(rc11Date(e.start,true))}</b><br>${rc13Safe(e.location||'Location to be confirmed')}</p><p>${rc13Safe(e.description||'')}</p>${e.url?`<a class="btn primary small" href="${rc13Safe(e.url)}" target="_blank" rel="noopener">Open event / training page</a>`:''}</article>`).join('')||'<div class="rc12-empty">No event currently available.</div>'}</div>`}
