function rc14OpenAddEvent(){const p=rc11AdminProfile(),regions=rc12AllowedRegions(p),clients=rc11VisibleClients();showModal(`<div class="rc11-modal-wide"><h3>Add event / training</h3><div class="rc12-modal-grid"><div class="field"><label>Title</label><input id="rc14EventTitle"></div><div class="field"><label>Type</label><select id="rc14EventType"><option>Training</option><option>Demonstration</option><option>Meeting</option><option>Webinar</option><option>Industry event</option><option>Other</option></select></div><div class="field"><label>Date & time</label><input id="rc14EventStart" type="datetime-local"></div><div class="field"><label>Location</label><input id="rc14EventLocation"></div><div class="field full"><label>Description</label><textarea id="rc14EventDesc" rows="3"></textarea></div><div class="field full"><label>Training / event URL</label><input id="rc14EventUrl" placeholder="https://..."></div><div class="field"><label>Audience</label><select id="rc14EventAudience"><option value="region">Region</option><option value="territory">Territory</option><option value="client">Professional</option><option value="all">All visible</option></select></div><div class="field"><label>Region</label><select id="rc14EventRegion">${regions.map(r=>`<option value="${r}">${rc13Safe(rc11RegionName(r))}</option>`).join('')}</select></div><div class="field"><label>Territory</label><select id="rc14EventTerritory"></select></div><div class="field"><label>Professional</label><select id="rc14EventClient">${clients.map(c=>`<option value="${c.id}">${rc13Safe(c.company)}</option>`).join('')}</select></div></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc14EventSave">Save event</button></div></div>`);const sync=()=>{$('rc14EventTerritory').innerHTML=rc12AllowedTerritories(p,$('rc14EventRegion').value).map(id=>`<option value="${id}">${rc13Safe(rc11Territory(id)?.name||id)}</option>`).join('')};$('rc14EventRegion').onchange=sync;sync();$('rc14EventSave').onclick=()=>{const title=$('rc14EventTitle').value.trim(),start=$('rc14EventStart').value;if(!title||!start)return toast('Title and date are required.');const aud=$('rc14EventAudience').value;rc14Settings().events.unshift({id:rc11SafeId('event'),title,type:$('rc14EventType').value,start:new Date(start).toISOString(),location:$('rc14EventLocation').value.trim(),description:$('rc14EventDesc').value.trim(),url:$('rc14EventUrl').value.trim(),audience:aud,regionIds:aud==='region'?[$('rc14EventRegion').value]:[],territoryIds:aud==='territory'?[$('rc14EventTerritory').value]:[],clientIds:aud==='client'?[$('rc14EventClient').value]:[],createdAt:new Date().toISOString()});saveStore();closeModal();renderShell();toast('Event published.')}}

/* Approval center. */
function renderApprovalsV14(){const p=rc11AdminProfile(),admins=rc14PendingAdmins(),pros=rc14PendingPros().filter(c=>rc14CanApproveProfessional(c,p));return rc11Hero('Registration approvals','Regional administrator registrations require USA HQ or Caribbean HQ approval. Professional registrations can be approved by HQ or by the authorized regional administrator for that territory.','ACCESS CONTROL','',[`${admins.length} admin request(s)`,`${pros.length} professional request(s)`])+`<section class="rc11-panel"><h3>Regional administrator requests</h3><div class="rc14-approval-grid">${admins.filter(a=>rc14CanApproveRegionalAdmin(p)).map(a=>`<article class="rc14-approval-card"><span class="rc14-dept">Regional administrator</span><h3>${rc13Safe(a.name)}</h3><p>${rc13Safe(a.company)}<br>${rc13Safe(a.email)}<br>${rc13Safe(rc11RegionName(a.regionId))} · ${rc13Safe(rc11Territory(a.territoryId)?.name||'')}</p><div class="toolbar"><button class="btn primary small" data-rc14-approve-admin="${a.id}">Approve</button><button class="btn danger small" data-rc14-reject-admin="${a.id}">Reject</button></div></article>`).join('')||'<div class="rc12-empty">No regional administrator request available to you.</div>'}</div></section><section class="rc11-panel" style="margin-top:14px"><h3>Professional requests</h3><div class="rc14-approval-grid">${pros.map(c=>`<article class="rc14-approval-card"><span class="rc14-dept">${rc13Safe(c.clientType||'Professional')}</span><h3>${rc13Safe(c.company)}</h3><p>${rc13Safe(rcClientName(c))}<br>${rc13Safe(c.email)}<br>${rc13Safe(rc11RegionName(c.regionId))} · ${rc13Safe(rc11Territory(c.territoryId)?.name||'')}<br>${rc14ProfileDocs(c.id).length}/4 required documents stored on this device</p><div class="toolbar"><button class="btn primary small" data-rc14-approve-pro="${c.id}">Approve</button><button class="btn secondary small" data-rc13-client-sheet="${c.id}">Review profile</button><button class="btn danger small" data-rc14-reject-pro="${c.id}">Reject</button></div></article>`).join('')||'<div class="rc12-empty">No professional request available to you.</div>'}</div></section>`}
async function rc14NotifyApproval(email,name,role){if(!email)return;const subject='RENOVO CRETE — Access approved',body=`Hello ${name||''},\n\nYour ${role} registration has been approved. You can now sign in with the email and password you selected during pre-registration.\n\nRENOVO CRETE`;try{await rc14DeliverEmail(email,subject,body)}catch(e){}}
async function rc14ApproveAdmin(id){const p=rc11AdminProfile(),a=(store.adminProfiles||[]).find(x=>x.id===id);if(!a||!rc14CanApproveRegionalAdmin(p))return toast('HQ approval required.');a.active=true;a.status='approved';const acc=(store.accounts||[]).find(x=>x.adminProfileId===id);if(acc){acc.active=true;acc.status='approved'}delete rc13Settings().registrationReservations[a.territoryId];rc14Settings().approvalHistory.unshift({type:'admin',id,action:'approved',by:p.name,at:new Date().toISOString()});saveStore();await rc14NotifyApproval(a.email,a.name,'regional administrator');toast('Regional administrator approved.');renderShell()}
function rc14RejectAdmin(id){const p=rc11AdminProfile(),a=(store.adminProfiles||[]).find(x=>x.id===id);if(!a||!rc14CanApproveRegionalAdmin(p))return;delete rc13Settings().registrationReservations[a.territoryId];store.accounts=(store.accounts||[]).filter(x=>x.adminProfileId!==id);store.adminProfiles=(store.adminProfiles||[]).filter(x=>x.id!==id);saveStore();toast('Regional administrator request rejected and territory released.');renderShell()}
async function rc14ApprovePro(id){const c=(store.accounts||[]).find(x=>x.id===id&&x.role==='client');if(!c||!rc14CanApproveProfessional(c))return toast('No approval permission.');c.active=true;c.status='approved';c.loginPending=false;rc14Settings().approvalHistory.unshift({type:'professional',id,action:'approved',by:rc11AdminProfile()?.name||'',at:new Date().toISOString()});saveStore();await rc14NotifyApproval(c.email,rcClientName(c),'professional');toast('Professional account approved.');closeModal();renderShell()}
function rc14RejectPro(id){const c=(store.accounts||[]).find(x=>x.id===id&&x.role==='client');if(!c||!rc14CanApproveProfessional(c))return;c.active=false;c.status='rejected';saveStore();toast('Professional application rejected.');closeModal();renderShell()}

/* Administrator AI customer service — same secure xAI proxy configuration as professional support. */
function renderAdminSupportV14(){const a=rc12Settings().assistant;return rc11Hero('Administrator customer service AI','Ask product, system, order, pricing, administration or technical-documentation questions from the administrator portal.','xAI REALTIME ASSISTANT','',[`${rc13Safe(a.agentId)}`])+`<div class="rc12-customer-service rc14-assistant-admin"><div class="rc12-assistant"><div class="rc12-assistant-head"><div><b>RENOVO CRETE Administrator Assistant</b><small>xAI Realtime · ${rc13Safe(a.language.toUpperCase())} · ${rc13Safe(a.voiceGender)} / ${rc13Safe(a.voiceAge)}</small></div><span class="rc11-status ${a.enabled?'ok':'warn'}">${a.enabled?'Enabled':'Disabled'}</span></div><div class="rc12-assistant-body" id="rc12AssistantBody"><div class="rc12-ai-msg">Ask a question about systems, product roles, simulations, orders, invoices, regions or portal operations. Live voice/text uses the secure server-side xAI Realtime proxy configured in Settings.</div></div><div class="rc12-ai-compose"><input id="rc12AssistantInput" placeholder="Ask the administrator assistant…" ${a.enabled?'':'disabled'}><button class="btn primary" id="rc12AssistantSend" ${a.enabled?'':'disabled'}>Send</button></div></div><aside class="rc12-panel"><h3 style="margin-top:0">Realtime configuration</h3><p><b>Agent ID</b><br>${rc13Safe(a.agentId||'Not configured')}</p><p><b>Secure proxy</b><br>${a.proxyUrl?'Configured':'Not configured'}</p><div class="notice warn"><b>XAI_API_KEY is never embedded in this HTML.</b><br>Your Node WebSocket example is server-side code. Production must proxy the Realtime connection through a protected backend.</div></aside></div>`}

/* Settings: transactional email and professional product-order email option. */
function rc14GovernancePanel(){const s=rc14Settings(),p=rc11AdminProfile(),scope=p?.regionId==='CARIBBEAN'?'REGION:CARIBBEAN':`TERRITORY:${p?.territoryId||''}`,allow=s.productOrderEmailByScope[scope]===true;return`<section class="rc11-panel" style="margin-top:14px"><div class="rc11-section-head"><div><span class="eyebrow">ACCESS DELIVERY</span><h3>Credentials, product orders & email connector</h3><p>Automatic email sending requires a secure server-side endpoint. Individual sends fall back to a prepared email draft if the endpoint is blank.</p></div></div><div class="rc12-modal-grid"><div class="field full"><label>Transactional email proxy URL</label><input id="rc14EmailProxy" value="${rc13Safe(s.transactionalEmail.proxyUrl||'')}" placeholder="https://your-domain/api/send-email"></div><div class="field"><label>Sender name</label><input id="rc14EmailFrom" value="${rc13Safe(s.transactionalEmail.fromName||'RENOVO CRETE')}"></div><div class="field"><label>Reply-to email</label><input id="rc14EmailReply" value="${rc13Safe(s.transactionalEmail.replyTo||'')}"></div><label class="permission-line full"><input id="rc14AllowOrderEmail" type="checkbox" ${allow?'checked':''}> Allow professionals in my pricing/territory scope to also send Product Order by email. Orders always remain routed to the responsible administration portal.</label></div><div class="toolbar"><button class="btn primary" id="rc14SaveDeliverySettings">Save access-delivery settings</button></div></section>`}

/* Product order routing metadata: every new order is tied to client region/territory and responsible admin scope. */
const rc14BaseSendOrder=sendOrder;
sendOrder=function(){const c=currentClient(),before=(tenantData()?.orders||[]).length;const out=rc14BaseSendOrder();const orders=store.tenants[c?.id]?.orders||[];const o=orders[0];if(o&&orders.length>before){o.regionId=c.regionId;o.territoryId=c.territoryId;o.responsibleScope=rc14ScopeKeyForClient(c);o.routedAt=new Date().toISOString();saveStore()}return out}

