/* V14.1 — invoice education, admin credentials, order export and product-order email */
function rc14BrandLogo(){return document.querySelector('.brand img')?.src||document.querySelector('.auth-brand img')?.src||''}
function rc14ProductRole(name=''){const s=String(name).toUpperCase();if(s.includes('E100-VB5')||s.includes('VB5'))return'Vapor barrier / moisture-control primer';if(s.includes('E100-PT4')||s.includes('PT4'))return'Pigmented epoxy base coat / broadcast coat';if(s.includes('E100-PT1')||s.includes('PT1'))return'Clear epoxy base coat / clear top coat / mortar binder';if(s.includes('REFLECTOR')&&s.includes('ENHANCER'))return'Decorative pigment added to compatible clear epoxy resin';if(s.includes('FS9'))return'Crack-bridging membrane / crack treatment layer';if(s.includes('FS4'))return'Flexible epoxy base coat';if(s.includes('PTG'))return'Cove-base resin gel / detail work';if(s.includes('NOVOLAC')||s.includes('NV4')||s.includes('NV5'))return'Chemical-resistant Novolac coating';if(s.includes('4.8S'))return'Urethane cement body coat';if(s.includes('SPARTIC')||s.includes('AUS-'))return'Protective performance top coat';return'System material — confirm role against the selected system build-up'}
function rc14CoverageBasis(item,areaM2=0){if(Number(item.need)>0&&Number(item.rate)>0)return`${num.format(item.need)} required · application rate ${num.format(item.rate)} ${rc13Safe(item.rateUnit||'')}`;if(/VB5/i.test(item.product||''))return'Elite Crete TDS reference: approx. 250–300 sq ft / 23.2–27.8 m² per US gallon on CSP 3 concrete';if(areaM2)return`Purchased quantity calculated for ${num.format(areaM2)} m² / ${num.format(areaM2*SQFT_PER_M2)} sq ft project area`;return'Coverage basis to validate from current technical data'}
function rc14BusinessDocStatus(c){return rc14ProfileDocs(c?.id||'').some(d=>d.type==='business')?'Kbis / business registration document on file':'Kbis / business registration document not uploaded'}

/* Enrich cart lines with calculator layer/coverage metadata for later invoice teaching. */
const rc14bBaseAddToCart=addToCart;
addToCart=function(){const r=result?JSON.parse(JSON.stringify(result)):null,c=currentClient();const out=rc14bBaseAddToCart();if(r&&c){const t=store.tenants[c.id];for(const l of(r.lines||[]))for(const p of(l.pack?.rows||[])){const matches=(t.cart||[]).filter(x=>x.systemId===r.system?.id&&x.product===l.productName&&x.pack===p.label);for(const x of matches)Object.assign(x,{layerName:l.layer?.name||'',layerRole:rc14ProductRole(l.productName),need:l.need,rate:l.rate,rateUnit:l.layer?.rateUnit||'',purchased:l.pack?.purchased,remainder:l.pack?.remainder,systemAreaM2:r.areaM2,systemAreaSqft:r.areaSqft})}saveStore()}return out}
if(typeof rc101AddResultToCart==='function'){const rc14bBaseAddResult=rc101AddResultToCart;rc101AddResultToCart=function(r){rc14bBaseAddResult(r);const t=tenantData();for(const l of(r.lines||[]))for(const p of(l.pack?.rows||[])){for(const x of(t.cart||[]).filter(x=>x.systemId===r.system?.id&&x.product===l.productName&&x.pack===p.label))Object.assign(x,{layerName:l.layer?.name||'',layerRole:rc14ProductRole(l.productName),need:l.need,rate:l.rate,rateUnit:l.layer?.rateUnit||'',purchased:l.pack?.purchased,remainder:l.pack?.remainder,systemAreaM2:r.areaM2,systemAreaSqft:r.areaSqft})}}}

/* Two-page invoice with RENOVO CRETE logo, company/legal data, exact product roles and coverage basis. */
rc11OpenInvoice=function(number){const x=rc11FindInvoice(number);if(!x)return toast('No permission.');const v=x.invoice,found=rc13FindOrderForInvoice(v),o=found?.order||{},c=found?.client||x.client,systemId=o.systemId||(o.items||[]).find(i=>i.systemId)?.systemId||'',systemName=v.systemName||o.systemName||rcSystemKey(o),items=v.items||o.items||[],areaM2=Number(o.areaM2||(items||[]).find(i=>i.systemAreaM2)?.systemAreaM2||0),areaSqft=areaM2*SQFT_PER_M2,check=rc13TechnicalChecklist(o.comment||o.siteNotes||v.notes||''),layers=(SYSTEMS.find(s=>s.id===systemId)?.layers||[]).map((l,i)=>`<li><b>${i+1}. ${rc13Safe(l.name)}</b>${l.rate?` — ${num.format(l.rate)} ${rc13Safe(l.rateUnit||'')}`:''}</li>`).join(''),logo=rc14BrandLogo(),businessDoc=rc14BusinessDocStatus(c);showModal(`<article class="rc11-invoice-sheet rc13-invoice-two-page"><section class="rc13-invoice-page"><header><div style="display:flex;align-items:center;gap:12px">${logo?`<img src="${logo}" alt="RENOVO CRETE" style="width:115px;height:58px;object-fit:contain">`:''}<div><small>INVOICE / MATERIAL SUPPLY</small><h2>${rc13Safe(v.number)}</h2><p>${rc13Safe(rc11Date(v.issuedAt))}</p></div></div><div class="invoice-brand"><b>RENOVO CRETE</b><span>${rc13Safe(rc11RegionName(v.regionId||c?.regionId))} · ${rc13Safe(rc11TerritoryLabel(v.territoryId||c?.territoryId))}</span><br><small>Territory-specific numbered invoice</small></div></header><div class="rc11-invoice-parties"><section><small>Professional / company</small><h3>${rc13Safe(c?.legalName||v.company||c?.company||'')}</h3><p><b>Contact:</b> ${rc13Safe(v.clientName||rcClientName(c)||'')}<br><b>Email:</b> ${rc13Safe(v.email||c?.email||'')}<br><b>Phone:</b> ${rc13Safe(c?.phone||'—')}<br><b>Address:</b> ${rc13Safe(c?.address1||v.address||'—')} ${rc13Safe(c?.address2||'')}<br>${rc13Safe([c?.postalCode,c?.city,c?.country].filter(Boolean).join(' · '))}<br><b>Registration / SIRET / SIREN:</b> ${rc13Safe(c?.registrationNumber||c?.siret||'—')}<br><b>Company file:</b> ${rc13Safe(businessDoc)}</p></section><section><small>Project / order</small><h3>${rc13Safe(v.orderNumber)}</h3><p>${rc13Safe(v.project||o.project||'')}<br><b>System:</b> ${rc13Safe(systemName)}<br>${areaM2?`<b>Area:</b> ${num.format(areaM2)} m² / ${num.format(areaSqft)} sq ft`:''}<br><b>Territory:</b> ${rc13Safe(rc11TerritoryLabel(v.territoryId||c?.territoryId))}</p></section></div><h3>Products, exact role, quantity & cost</h3><div class="table-wrap"><table class="rc11-table"><thead><tr><th>Layer / role</th><th>Exact product</th><th>Pack</th><th>Qty</th><th>Unit price</th><th>Total</th><th>Coverage / calculation basis</th></tr></thead><tbody>${items.map(i=>`<tr><td><b>${rc13Safe(i.layerName||rc14ProductRole(i.product||''))}</b><br><small>${rc13Safe(i.layerRole||rc14ProductRole(i.product||''))}</small></td><td>${rc13Safe(i.product||i.systemName||systemName)}</td><td>${rc13Safe(i.pack||'—')}</td><td>${num.format(Number(i.quantity||0))}</td><td>${rc11Money(i.unitPriceEUR||0)}</td><td><b>${rc11Money(i.totalEUR||0)}</b></td><td>${rc13Safe(rc14CoverageBasis(i,areaM2))}</td></tr>`).join('')||'<tr><td colspan="7">No product line available.</td></tr>'}</tbody></table></div><div class="rc11-invoice-total"><div><span>Total EUR</span><b>${rc11Money(v.totalEUR||o.totalEUR||0)}</b></div>${(v.totalUSD||o.totalUSD)?`<div><span>Total USD</span><b>${rc11Money(v.totalUSD||o.totalUSD,'USD')}</b></div>`:''}<div class="grand"><span>Invoice total</span><b>${rc11Money(v.totalEUR||o.totalEUR||0)}</b></div></div><div class="rc13-invoice-note"><b>Territory numbering:</b> this invoice sequence belongs only to ${rc13Safe(rc11TerritoryLabel(v.territoryId||c?.territoryId))}. Other islands, countries and US states use independent numbering sequences.</div></section><section class="rc13-invoice-page"><header><div style="display:flex;align-items:center;gap:12px">${logo?`<img src="${logo}" alt="RENOVO CRETE" style="width:105px;height:52px;object-fit:contain">`:''}<div><small>SYSTEM & INSTALLATION PLANNING</small><h2>${rc13Safe(systemName)}</h2></div></div><div class="invoice-brand"><b>Page 2 / 2</b><span>Educational project summary</span></div></header><div class="rc13-invoice-visual-grid"><div>${rc13SystemVisual(systemId,systemName)}</div><div><h3>System layers / sequence</h3><ol>${layers||'<li>Layer sequence to be validated from the current system technical documentation.</li>'}</ol><h3>Product-role reminders</h3><ul>${[...new Set(items.map(i=>`${i.product||''} — ${i.layerRole||rc14ProductRole(i.product||'')}`))].map(x=>`<li>${rc13Safe(x)}</li>`).join('')}</ul></div></div><h3>Project comments & substrate points to plan</h3><p>${rc13Safe(o.comment||o.siteNotes||v.notes||'No specific project comment recorded.')}</p><ul>${check.map(x=>`<li>${rc13Safe(x)}</li>`).join('')}</ul><div class="rc11-security-banner"><b>Technical validation:</b> product roles shown here are educational aids. Final selection, coverage, substrate preparation, PPE and application sequence must be checked against the current Elite Crete Systems technical data, SDS, submittal package and project conditions before installation.</div></section><div class="toolbar rc11-no-print"><button class="btn secondary" onclick="closeModal()">Close</button><button class="btn primary" onclick="window.print()">Print / Save PDF — 2 pages maximum</button></div></article>`)}

/* Administrator credentials: each admin has an email login and can receive a newly generated password. */
async function rc14IssueAdminCredential(profileId){const p=rc11AdminProfile(),a=(store.adminProfiles||[]).find(x=>x.id===profileId);if(!a||!(rc12IsWorldHq(p)||rc12IsCaribbeanHq(p)||a.id===p?.id))return toast('No permission to issue administrator credentials.');const acc=(store.accounts||[]).find(x=>x.adminProfileId===a.id);if(!acc||!a.email)return toast('Administrator login account/email is missing.');const pw=rc12GeneratePassword();acc.passwordHash=await hashText(pw);a.lastCredentialIssuedAt=new Date().toISOString();saveStore();const subject='RENOVO CRETE — Administrator portal credentials',body=`Hello ${a.name||''},\n\nYour administrator portal credentials have been updated.\n\nLogin / email: ${a.email}\nTemporary password: ${pw}\n\nRENOVO CRETE`;try{const mode=await rc14DeliverEmail(a.email,subject,body);toast(mode==='sent'?'Administrator credentials sent.':'Administrator credential email draft prepared.')}catch(e){toast('Password updated, but email delivery failed.')}}
function rc14ConfirmAdminCredential(id){const a=(store.adminProfiles||[]).find(x=>x.id===id);if(!a)return;showModal(`<h3>Generate new administrator login?</h3><p><b>${rc13Safe(a.name)}</b><br>Login: ${rc13Safe(a.email)}</p><div class="notice warn">The existing password will stop working. The new plaintext password is not stored after the email/draft is prepared.</div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" id="rc14AdminCredentialConfirm">Generate & send</button></div>`);$('rc14AdminCredentialConfirm').onclick=async()=>{closeModal();await rc14IssueAdminCredential(id)}}
const rc14bBaseAdminSheet=rc13OpenAdminSheet;
rc13OpenAdminSheet=function(id){rc14bBaseAdminSheet(id);const a=(store.adminProfiles||[]).find(x=>x.id===id),card=document.querySelector('.modal-card .rc13-profile-sheet');if(!a||!card)return;const tb=card.querySelector('.toolbar');if(tb&&(rc12IsWorldHq()||rc12IsCaribbeanHq()||a.id===rc11AdminProfile()?.id)){const b=document.createElement('button');b.className='btn dark';b.textContent='Generate & send administrator login';b.dataset.rc14AdminCredential=id;tb.insertBefore(b,tb.lastElementChild)}}

/* Optional product-order email copy while primary routing remains portal-based. */
function rc14ResponsibleAdminEmails(c){const ps=store.adminProfiles||[];let list=[];if(c?.regionId==='CARIBBEAN')list=ps.filter(a=>a.level==='caribbean_hq'&&a.active!==false);else list=ps.filter(a=>a.level==='regional_admin'&&a.territoryId===c?.territoryId&&a.active!==false);if(!list.length)list=ps.filter(a=>a.level==='global_hq'&&a.active!==false);return [...new Set(list.map(a=>a.email).filter(Boolean))]}
const rc14bBaseRenderCart=renderCart;
renderCart=function(){const html=rc14bBaseRenderCart(),c=currentClient();if(!c)return html;const scope=rc14ScopeKeyForClient(c),allow=rc14Settings().productOrderEmailByScope[scope]===true;return html+`<section class="rc11-panel" style="margin-top:14px"><div class="rc11-section-head"><div><span class="eyebrow">ORDER ROUTING</span><h3>Regional administration</h3><p>Your submitted Product Order is routed only to the administration responsible for ${rc13Safe(rc11Territory(c.territoryId)?.name||'your territory')}. It is not sent to unrelated regional administrators.</p></div></div>${allow?`<button class="btn secondary" id="rc14EmailOrderCopy">Email a copy of this Product Order to regional administration</button>`:'<div class="notice">Email-copy access is disabled by your regional administrator. The normal portal order submission remains available.</div>'}</section>`}
async function rc14EmailOrderCopy(){const c=currentClient(),t=tenantData(),to=rc14ResponsibleAdminEmails(c);if(!to.length)return toast('No responsible administrator email is configured.');if(!(t.cart||[]).length)return toast('The Product Order cart is empty.');const total=t.cart.reduce((n,x)=>n+Number(x.totalEUR||0),0),subject=`RENOVO CRETE Product Order — ${c.company}`,body=`Professional: ${c.company}\nContact: ${rcClientName(c)}\nTerritory: ${rc11Territory(c.territoryId)?.name||''}\n\n${t.cart.map(x=>`${x.product} | ${x.pack} | Qty ${x.quantity} | ${rc11Money(x.totalEUR)}`).join('\n')}\n\nTotal: ${rc11Money(total)}\n\nThis is an email copy. The official order should also be submitted through the portal.`;try{const mode=await rc14DeliverEmail(to.join(','),subject,body);toast(mode==='sent'?'Product Order copy sent.':'Product Order email draft prepared.')}catch(e){toast('Unable to prepare/send the Product Order email copy.')}}

/* Select and export Global Orders after any active filters. */
const rc14bBaseRenderGlobalOrders=renderGlobalOrders;
renderGlobalOrders=function(){let html=rc14bBaseRenderGlobalOrders();html=html.replace(/<span class="rc11-number">/g,'<label class="rc14-select"><input type="checkbox" data-rc14-order-select> Select</label><span class="rc11-number">');return html+`<div class="rc14-toolbar"><button class="btn secondary" id="rc14SelectVisibleOrders">Select filtered/visible orders</button><button class="btn secondary" id="rc14ClearOrders">Clear selection</button><button class="btn primary" id="rc14ExportSelectedOrders">Export selected orders CSV</button><button class="btn secondary" id="rc14ExportVisibleOrders">Export filtered/visible orders CSV</button></div>`}
function rc14OrderRowsFromCards(cards){return cards.map(card=>{const key=card.querySelector('[data-rc11-order-open]')?.dataset.rc11OrderOpen||'',parts=key.split('|'),tid=parts[0],idx=Number(parts[1]),c=(store.accounts||[]).find(x=>x.id===tid),o=store.tenants[tid]?.orders?.[idx];if(!c||!o)return null;return{c,o}}).filter(Boolean)}
function rc14ExportOrderRows(rows){const csv=['Order,Date,Company,Contact,Region,Territory,System,Total EUR,Paid EUR,Outstanding EUR,Order status,Payment status',...rows.map(({c,o})=>[rc11OrderDisplay(o),rc11Date(o.createdAt),c.company,rcClientName(c),rc11RegionName(c.regionId),rc11Territory(c.territoryId)?.name||'',rcSystemKey(o),Number(o.totalEUR||0).toFixed(2),rcOrderPaid(o).toFixed(2),rcOrderBalance(o).toFixed(2),o.status||'',o.paymentStatus||''].map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(','))].join('\n');rc14DownloadText(`RENOVO_CRETE_Orders_${new Date().toISOString().slice(0,10)}.csv`,csv,'text/csv')}

/* Extend V14 bind layer without disturbing previous page bindings. */
const rc14bBaseBind=rc11BindController;
rc11BindController=function(){rc14bBaseBind();document.querySelectorAll('[data-rc14-admin-credential]').forEach(b=>b.onclick=()=>rc14ConfirmAdminCredential(b.dataset.rc14AdminCredential));if(currentView==='cart')$('rc14EmailOrderCopy')?.addEventListener('click',rc14EmailOrderCopy);if(currentView==='global-orders'){$('rc14SelectVisibleOrders')?.addEventListener('click',()=>document.querySelectorAll('[data-rc11-order]').forEach(card=>{if(card.style.display!=='none'){const cb=card.querySelector('[data-rc14-order-select]');if(cb)cb.checked=true}}));$('rc14ClearOrders')?.addEventListener('click',()=>document.querySelectorAll('[data-rc14-order-select]').forEach(x=>x.checked=false));$('rc14ExportSelectedOrders')?.addEventListener('click',()=>rc14ExportOrderRows(rc14OrderRowsFromCards([...document.querySelectorAll('[data-rc11-order]')].filter(c=>c.querySelector('[data-rc14-order-select]')?.checked))));$('rc14ExportVisibleOrders')?.addEventListener('click',()=>rc14ExportOrderRows(rc14OrderRowsFromCards([...document.querySelectorAll('[data-rc11-order]')].filter(c=>c.style.display!=='none'))))}}
if(!window.__rc14bDelegated){window.__rc14bDelegated=true;document.addEventListener('click',e=>{const b=e.target.closest('[data-rc14-admin-credential]');if(b){e.preventDefault();rc14ConfirmAdminCredential(b.dataset.rc14AdminCredential)}})}


